use std::sync::Mutex;

fn add_one(m: &Mutex<u32>) {
    let mut guard = m.lock().unwrap();
    *guard += 1;
    // guard drops here, unlocking Mutex
}

fn work(m: &Mutex<u32>) {
    let mut guard = m.lock().unwrap();
    *guard += 1;
    std::mem::drop(guard);
    // long computation runs unlocked
}
